<?php
declare(strict_types=1); namespace App\Services; use CodeIgniter\Database\BaseConnection; use InvalidArgumentException;
final class ProposalItemSupplierQuoteService {public function __construct(private ?BaseConnection$db=null){$this->db??=db_connect('default');}public function forItem(int$id):array{return$this->db->table('proposal_item_supplier_quotes q')->select('q.*,s.name supplier_name,s.rfc supplier_rfc,s.status supplier_status,s.deleted supplier_deleted')->join('suppliers s','s.id=q.supplier_id')->where(['q.proposal_item_id'=>$id,'q.deleted'=>0])->orderBy('q.is_selected','DESC')->orderBy('q.quoted_at','DESC')->orderBy('q.id','DESC')->get()->getResultArray();}public function save(int$itemId,array$in,int$user):array{$item=$this->item($itemId);$id=(int)($in['quote_id']??0);$sid=(int)($in['supplier_id']??0);$supplier=$this->db->table('suppliers')->where(['id'=>$sid,'deleted'=>0,'status'=>'active'])->get(1)->getRow();if(!$supplier)throw new InvalidArgumentException('Seleccione un proveedor activo.');$cost=(new CommercialMarginService())->normalize($in['unit_cost']??null,'Costo',true);$date=trim((string)($in['quoted_at']??''));if(!$this->date($date))throw new InvalidArgumentException('La fecha de la oferta no es válida.');$valid=trim((string)($in['valid_until']??''));if($valid!==''&&!$this->date($valid))throw new InvalidArgumentException('La vigencia no es válida.');$days=trim((string)($in['delivery_days']??''));if($days!==''&&(!ctype_digit($days)||(int)$days>3650))throw new InvalidArgumentException('Los días de entrega no son válidos.');$dup=$this->db->table('proposal_item_supplier_quotes')->where(['proposal_item_id'=>$itemId,'supplier_id'=>$sid,'unit_cost'=>$cost,'quoted_at'=>$date,'deleted'=>0]);if($id)$dup->where('id !=',$id);if($dup->countAllResults())throw new InvalidArgumentException('Esta oferta ya está registrada para la partida.');$now=get_current_utc_time();$data=['proposal_item_id'=>$itemId,'product_id'=>(int)$item->item_id,'supplier_id'=>$sid,'unit_cost'=>$cost,'quoted_at'=>$date,'valid_until'=>$valid?:null,'delivery_days'=>$days===''?null:(int)$days,'notes'=>trim((string)($in['notes']??''))?:null,'updated_at'=>$now];if($id){if(!$this->db->table('proposal_item_supplier_quotes')->where(['id'=>$id,'proposal_item_id'=>$itemId,'deleted'=>0])->countAllResults())throw new InvalidArgumentException('La oferta no existe.');$this->db->table('proposal_item_supplier_quotes')->where('id',$id)->update($data);}else{$data+=['is_selected'=>0,'created_by'=>$user?:null,'created_at'=>$now,'deleted'=>0];$this->db->table('proposal_item_supplier_quotes')->insert($data);$id=(int)$this->db->insertID();}return['id'=>$id,'supplier_id'=>$sid,'supplier_name'=>$supplier->name,'unit_cost'=>$cost];}public function select(int$itemId,int$quoteId):array{$item=$this->item($itemId);$this->db->transBegin();try{$q=$this->db->query('SELECT * FROM '.$this->db->prefixTable('proposal_item_supplier_quotes').' WHERE id=? AND proposal_item_id=? AND deleted=0 FOR UPDATE',[$quoteId,$itemId])->getRow();if(!$q)throw new InvalidArgumentException('La oferta no existe.');$supplier=$this->db->table('suppliers')->where(['id'=>$q->supplier_id,'deleted'=>0,'status'=>'active'])->get(1)->getRow();if(!$supplier)throw new InvalidArgumentException('El proveedor está inactivo y no puede seleccionarse.');$margin=(new CommercialMarginService())->marginFromPrice((string)$q->unit_cost,(string)$item->rate);$now=get_current_utc_time();$this->db->table('proposal_item_supplier_quotes')->where('proposal_item_id',$itemId)->update(['is_selected'=>0,'updated_at'=>$now]);$this->db->table('proposal_item_supplier_quotes')->where('id',$quoteId)->update(['is_selected'=>1,'updated_at'=>$now]);$this->db->table('proposal_items')->where('id',$itemId)->update(['supplier_id'=>$q->supplier_id,'cost'=>$q->unit_cost,'profit_percentage'=>$margin]);$this->db->transCommit();return['supplier_id'=>(int)$q->supplier_id,'supplier_name'=>$supplier->name,'unit_cost'=>(string)$q->unit_cost,'margin'=>$margin];}catch(\Throwable$e){$this->db->transRollback();throw$e;}}public function delete(int$itemId,int$quoteId):void{$this->item($itemId);if(!$this->db->table('proposal_item_supplier_quotes')->where(['id'=>$quoteId,'proposal_item_id'=>$itemId,'deleted'=>0])->countAllResults())throw new InvalidArgumentException('La oferta no existe.');$this->db->table('proposal_item_supplier_quotes')->where('id',$quoteId)->update(['deleted'=>1,'is_selected'=>0,'updated_at'=>get_current_utc_time()]);}private function item(int$id):object{$r=$this->db->table('proposal_items')->where(['id'=>$id,'deleted'=>0])->get(1)->getRow();if(!$r||!(int)$r->item_id)throw new InvalidArgumentException('La partida debe corresponder a un producto catalogado.');return$r;}private function date(string$v):bool{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);return$d&&$d->format('Y-m-d')===$v;}}
